import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade, Person } from './people';
import { Rate, atLeast, due, pctOn } from './rates';
import { Session } from './session';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk
 *  limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
 *  DRAFT, OPEN or PENDING claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A change of status a claim can be asked for. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject';

/** Whether a claim is open: OPEN, or PENDING approval of its settle. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim at this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** Whether a claim counts in the live totals: it counts, and it is not an open (or pending) claim
 *  of a person on hold. */
export function countsLive(c: Claim, held: boolean): boolean {
  return counts(c) && !(held && isOpen(c));
}

export interface Claim {
  id: number;
  personId: number;
  /** The amount as text with two decimals. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened (1, 2, ... or, under period numbering,
   *  <period name>-<n>, or X-<n> for a claim in no period); null for a claim never opened. */
  number: string | null;
  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
  settledDue: string | null;
  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
  openedBy: string | null;
  /** Whether its person's last statement bound it to the due it had then. */
  stated: boolean;
  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
   *  or was bound while it had no due (its due then stays live). */
  statedDue: string | null;
  /** The number of the settled claim this correction corrects; null when it is not a correction. */
  corrects: string | null;
  /** The date (yyyy-mm-dd) its figures round by: that of the claim a correction corrects, or else
   *  its own. */
  roundsBy: string;
  /** Where the claim is listed: claims are listed newest first by this (a claim moved to another
   *  person is listed as that person's newest). */
  listed: number;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import type { Claim } from './claims';
import { Session } from './session';

export type Grade = 'A' | 'B' | 'C';

/** A grade a person was given, from a day (yyyy-mm-dd); null: from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

/** The grade in force on a day: the one with the latest from-date on or before it, or else the one
 *  with no from-date; grades come earliest first. */
export function gradeOn(grades: GradeFrom[], day: string | null): Grade | undefined {
  let on: Grade | undefined;
  for (const g of grades) {
    if (g.from === null || (day !== null && g.from <= day)) on = g.grade;
  }
  return on;
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded for them, earliest first. */
  grades: GradeFrom[];
  /** Raised each time the person is saved. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total as text with two decimals; null when it was n/a or none was taken. */
  statedTotal: string | null;
  /** The day (yyyy-mm-dd) the last statement was taken; null when none was. */
  statementDate: string | null;
  /** Whether they are retired: they are as soon as a retirement day is set, whatever the day. */
  retired: boolean;
  /** The day (yyyy-mm-dd) they are retired from; null when they are not retired. */
  retiredFrom: string | null;
  /** Whether they are on hold: their open claims then count in no live total. */
  held: boolean;
}

/** A statement just taken: the person as they now show, and their claims (newest first) as it
 *  bound them. */
export interface Taken {
  person: Person;
  claims: Claim[];
}

export interface PersonForm {
  name: string;
  grade: Grade;
  /** The day (yyyy-mm-dd) an edit's grade applies from; null takes the sheet's today. */
  gradeFrom?: string | null;
}

// The people kept on the active sheet.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Person[]> {
    return firstValueFrom(this.http.get<Person[]>(this.url(sheetId)));
  }

  add(form: PersonForm): Promise<Person> {
    const { sheetId, user } = this.active();
    return firstValueFrom(this.http.post<Person>(this.url(sheetId), form, { headers: { 'X-User': user } }));
  }

  /** Save over the version of the person the editor loaded; refused (412) when another user has
   *  saved them since. */
  edit(id: number, version: number, form: PersonForm): Promise<Person> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.put<Person>(`${this.url(sheetId)}/${id}`, { ...form, version }, { headers: { 'X-User': user } }),
    );
  }

  /** Retire the person from a day; null takes the sheet's today. */
  retire(id: number, from: string | null): Promise<Person> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheetId)}/${id}/retire`, { from }, { headers: { 'X-User': user } }),
    );
  }

  /** Put the person on hold (true) or take them off it (false). */
  hold(id: number, held: boolean): Promise<Person> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheetId)}/${id}/hold`, { held }, { headers: { 'X-User': user } }),
    );
  }

  /** Take a statement of the person: their due-total now is recorded and each claim of theirs that
   *  counts is bound to the figure it has now. */
  statement(id: number): Promise<Taken> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Taken>(`${this.url(sheetId)}/${id}/statements`, null, { headers: { 'X-User': user } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }

  private active(): { sheetId: string; user: string } {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return { sheetId, user };
  }
